 for i := 1 to n-1 do
 for j := i + 1 to n do 
 if arrayAB[i, 1] > arrayAB[j, 1] then begin
 t1 := arrayAB[i, 1];
 t2 := arrayAB[i, 2];
 arrayAB[i, 1] := arrayAB[j, 1];
