 k62: integer; {количество требуемых пар}
 i: integer;
 f: text;
begin
n62:=0; n31:=0; n2:=0;
assign(f,'27989_A.txt');
reset(f);
readln(f, n);
for i := 1 to n do begin
readln(f, a); 
if a mod 62 = 0 then
 n62 := n62+1
 else if a mod 31 = 0 then
 n31:= n31 + 1
 else if a mod 2 = 0 then
 n2 := n2 + 1;
 end;
 k62 := n62*(n62-1) div 2 + n62*(N-n62) + n2*n31;
 writeln(k62)
end.
